//! Language-neutral wire vectors (tests/data/*.bin) generated by tools/gen_vectors.py / gen_testvec.py from an
//! independent Python reference encoder. The same vectors drive the C++ tests.
use mcscon::inflate::zlib_inflate;
use mcscon::packets::cb::decode_by_name;
use mcscon::wire::Reader;
use mcscon::Version;
use std::collections::BTreeMap;

static PACKETS: &[u8] = include_bytes!("data/packet_vectors.bin");
static ZLIB: &[u8] = include_bytes!("data/zlib_vectors.bin");

struct PVec {
    ver: Version,
    name: &'static str,
    d: &'static [u8],
}

fn packet_vectors() -> Vec<PVec> {
    let mut out = Vec::new();
    let mut p = PACKETS;
    while !p.is_empty() {
        let ver = Version::from_u8(p[0]).unwrap();
        let nl = p[1] as usize;
        let name = std::str::from_utf8(&p[2..2 + nl]).unwrap();
        let len = u32::from_le_bytes(p[2 + nl..6 + nl].try_into().unwrap()) as usize;
        out.push(PVec { ver, name, d: &p[6 + nl..6 + nl + len] });
        p = &p[6 + nl + len..];
    }
    out
}

/// Every random valid packet from the independent reference encoder must decode and consume exactly all bytes.
#[test]
fn all_vectors_decode_exactly() {
    let mut failed: BTreeMap<String, i32> = BTreeMap::new();
    let mut total = 0;
    for pv in packet_vectors() {
        let mut r = Reader::new(pv.d);
        let ok = decode_by_name(pv.name, &mut r, pv.ver);
        total += 1;
        if !ok || r.left() != 0 || !r.ok() {
            *failed.entry(format!("{}@{:?}", pv.name, pv.ver)).or_insert(0) += 1;
        }
    }
    println!("{} vectors, {} failing packet/version pairs", total, failed.len());
    assert!(total > 10000);
    assert!(failed.is_empty(), "mismatches: {:?}", failed);
}

/// Truncation / corruption must never panic or read out of bounds.
#[test]
fn robust_against_truncation_and_corruption() {
    let mut seed = 5u32;
    let mut rnd = || {
        seed = seed.wrapping_mul(1103515245).wrapping_add(12345);
        (seed >> 8) as usize
    };
    for pv in packet_vectors() {
        let mut cut = 0;
        while cut < pv.d.len() {
            let mut r = Reader::new(&pv.d[..cut]);
            decode_by_name(pv.name, &mut r, pv.ver);
            cut += 1 + pv.d.len() / 8;
        }
        if pv.d.len() > 2048 {
            continue;
        }
        for _ in 0..8 {
            let mut buf = pv.d.to_vec();
            if !buf.is_empty() {
                let i = rnd() % buf.len();
                buf[i] = rnd() as u8;
            }
            let mut r = Reader::new(&buf);
            decode_by_name(pv.name, &mut r, pv.ver);
        }
    }
}

/// Negative control: dropping the last byte must make decoding fail, except for packets whose final field is a
/// "rest of packet" buffer (or optional trailing data).
#[test]
fn negative_control_pins_layouts() {
    let mut survivors: BTreeMap<&str, i32> = BTreeMap::new();
    let mut tried = 0;
    for pv in packet_vectors() {
        if pv.d.is_empty() {
            continue;
        }
        let mut r = Reader::new(&pv.d[..pv.d.len() - 1]);
        tried += 1;
        if decode_by_name(pv.name, &mut r, pv.ver) {
            *survivors.entry(pv.name).or_insert(0) += 1;
        }
    }
    assert!(tried > 10000);
    for (name, _) in survivors {
        assert!(name == "CustomPayload" || name == "TabComplete" || name == "Map", "{name} survives truncation");
    }
}

fn fnv(b: &[u8]) -> u32 {
    let mut h: u32 = 2166136261;
    for &c in b {
        h = (h ^ c as u32).wrapping_mul(16777619);
    }
    h
}

#[test]
fn zlib_vectors_inflate_and_verify() {
    let mut p = ZLIB;
    let mut n = 0;
    while !p.is_empty() {
        let nl = p[0] as usize;
        let name = std::str::from_utf8(&p[1..1 + nl]).unwrap();
        let rd = |o: usize| u32::from_le_bytes(p[1 + nl + o..5 + nl + o].try_into().unwrap()) as usize;
        let (zlen, rawlen, want) = (rd(0), rd(4), rd(8) as u32);
        let z = &p[13 + nl..13 + nl + zlen];
        let mut out = vec![0u8; rawlen];
        assert_eq!(zlib_inflate(z, &mut out, true), Some(rawlen), "{name}");
        assert_eq!(fnv(&out), want, "{name}");
        // too small an output buffer must fail instead of overflowing
        if rawlen > 0 {
            let mut small = vec![0u8; rawlen - 1];
            assert_eq!(zlib_inflate(z, &mut small, false), None, "{name} overflow");
        }
        // a flipped checksum byte must fail verification
        let mut bad = z.to_vec();
        let l = bad.len();
        bad[l - 1] ^= 0xFF;
        assert_eq!(zlib_inflate(&bad, &mut out, true), None, "{name} adler");
        // truncations never panic
        for cut in 0..z.len().min(200) {
            let _ = zlib_inflate(&z[..cut], &mut out, true);
        }
        p = &p[13 + nl + zlen..];
        n += 1;
    }
    assert_eq!(n, 6);
}
